package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.ReleaseVO;

class ReleaseValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of release of observed issue")
  void test_release_value_holder_assign_plain_value() {
    Object holder = new Object();
    ReleaseValueHolder<Object> value = new ReleaseValueHolder<>(holder);
    Assertions.assertSame(holder, value.release("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getReleaseValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getRelease().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.releaseNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getReleaseValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getRelease().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of release of observed issue")
  void test_release_value_holder_assign_value_object() {
    Object holder = new Object();
    ReleaseValueHolder<Object> value = new ReleaseValueHolder<>(holder);
    ReleaseVO vo = ReleaseVO.from("one");
    Assertions.assertFalse(value.getReleaseValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.release(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getReleaseValue().orElseThrow());
    Assertions.assertSame(holder, value.release(Optional.empty()));
    Assertions.assertFalse(value.getReleaseValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.release(Optional.of(vo)));
    Assertions.assertSame(vo, value.getReleaseValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of release of observed issue against the original")
  void test_release_value_holder_read() {
    Object holder = new Object();
    ReleaseValueHolder<Object> value = new ReleaseValueHolder<>(holder);
    ReleaseVO vo = ReleaseVO.from("one");
    ReleaseVO other = ReleaseVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getReleaseValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRelease(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readRelease(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.release(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRelease(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRelease(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of release of observed issue")
  void test_release_value_holder_unset() {
    Object holder = new Object();
    ReleaseValueHolder<Object> value = new ReleaseValueHolder<>(holder);
    ReleaseVO vo = ReleaseVO.from("one");
    value.release(vo);
    Assertions.assertSame(holder, value.unsetReleaseIfMatches("release_other"));
    Assertions.assertTrue(value.getReleaseValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetReleaseIfMatches("release"));
    Assertions.assertFalse(value.getReleaseValue().isPresent(),
        "The field name must clear the value");
    value.release(vo);
    Assertions.assertSame(holder, value.unsetRelease());
    Assertions.assertFalse(value.getReleaseValue().isPresent(), "Unset must clear the value");
  }
}
